from idc import *

def run(n=12,roll=.24,yaw=.3):
 s.reset();q0=d.qpos.copy();a0=d.actuator_length.copy();actions=[]
 for t in range(100):
  target=a0.copy()
  if t<n:
   target[[2,7]]=-.05;target[[3,8]]=.1;target[[4,9]]=-.05
  else:
   target[[0,5]]=[yaw,-yaw];target[[1,6]]=[roll,-roll];target[[2,7]]=-.4;target[[3,8]]=.8;target[[4,9]]=-.4
  a=np.clip(2*(target-r[:,0])/(r[:,1]-r[:,0])-1,-1,1);_,_,done=s.step(a);actions.append(a)
  if t%10==0:print(t,d.qpos[:3],d.site_xpos[[1,2]])
  if done:break
 np.save('/app/widenactions.npy',actions);np.save('/app/widenq.npy',d.qpos)
if __name__=='__main__':run()
